const __pageData = JSON.parse('{"title":"Worked answers — numbers in a box","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"materials/week-03/instructor/answers.md","filePath":"materials/week-03/instructor/answers.md"}');
